import { h } from "@stencil/core";

import type { MatrixChartConfig } from "./matrix.d";

import { checkSquare, info, minus, plus } from "../../../icons";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import {
  applyStylesFromState,
  isZoomDisabled,
  onCtrlPanelKeyDown,
  setCellStyleFromStateEvent,
} from "./chart-util";

const updateLabelContainer = (
  querySelector: string,
  host,
  paddingTop: number,
  paddingLeft: number
) => {
  const target = host.shadowRoot.querySelector(querySelector) as SVGGElement;
  if (target) {
    target.setAttribute(
      "transform",
      `translate(${paddingLeft}, ${paddingTop})`
    );
  }
};

const generateAxis = (
  data,
  blockSize: number,
  gapSize: number,
  labelObj,
  paddingTop: number,
  paddingLeft: number,
  position: "top" | "left" | "right" | "bottom",
  host?: HTMLElement
) => {
  const positionClass = `axis-${position}`;
  const translateX = position === "left" ? 0 : paddingLeft;
  const translateY = position === "top" ? 0 : paddingTop;
  const labelWidth =
    position === "left" || position === "right" ? labelObj.width : blockSize;
  const labelHeight =
    position === "top" || position === "bottom" ? labelObj.height : blockSize;

  // stenciljs does not hydrate svg
  updateLabelContainer(`g.${positionClass}`, host, paddingTop, paddingLeft);

  const { render = (label) => label, axisTemplate } = labelObj;

  return (
    <g
      class={positionClass}
      transform={`translate(${translateX}, ${translateY})`}
    >
      {data.map((label, index) => {
        const x =
          position === "left" || position === "right"
            ? 0
            : index * (blockSize + gapSize);
        const y =
          position === "top" || position === "bottom"
            ? 0
            : index * (blockSize + gapSize);
        return (
          <g
            key={`${position}-${label}`}
            width={labelWidth}
            height={labelHeight}
            x={x}
            y={y}
            class="axis-group"
          >
            <foreignObject data-label={label}>
              {axisTemplate ? (
                <div part={positionClass}>{axisTemplate(h, label, index)}</div>
              ) : (
                <div part={positionClass} innerHTML={render(label, index)} />
              )}
            </foreignObject>
          </g>
        );
      })}
    </g>
  );
};

const generateAxisTop = (
  data,
  blockSize,
  gapSize,
  labelTopObj,
  paddingLeft,
  host
) =>
  generateAxis(
    data,
    blockSize,
    gapSize,
    labelTopObj,
    0,
    paddingLeft,
    "top",
    host
  );

const generateAxisLegendLeft = (
  data,
  blockSize,
  gapSize,
  labelLeftObj,
  paddingTop,
  host
) =>
  generateAxis(
    data,
    blockSize,
    gapSize,
    labelLeftObj,
    paddingTop,
    0,
    "left",
    host
  );

const generateAxisRight = (
  data,
  blockSize,
  gapSize,
  labelRightObj,
  paddingTop,
  paddingLeft,
  host
) => {
  return generateAxis(
    data,
    blockSize,
    gapSize,
    labelRightObj,
    paddingTop,
    paddingLeft,
    "right",
    host
  );
};

const generateAxisBottom = (
  data,
  blockSize,
  gapSize,
  labelBottomObj,
  paddingTop,
  paddingLeft,
  host
) =>
  generateAxis(
    data,
    blockSize,
    gapSize,
    labelBottomObj,
    paddingTop,
    paddingLeft,
    "bottom",
    host
  );

const setAxisHoveringState = (
  root: ShadowRoot,
  row: string,
  col: string,
  show: boolean
) => {
  const axisSelectors = [
    { selector: ".axis-top", label: col },
    { selector: ".axis-left", label: row },
    { selector: ".axis-right", label: row },
    { selector: ".axis-bottom", label: col },
  ];

  axisSelectors.forEach(({ selector, label }) => {
    const axisElement = root
      .querySelector(selector)
      ?.querySelector(`[data-label="${label}"]`);
    if (axisElement) {
      show
        ? axisElement.classList.add("--hover")
        : axisElement.classList.remove("--hover");
    }
  });
};

const setDefaultItemTooltipTemplate = (
  createElement,
  row,
  col,
  obj,
  fullConfig
) => {
  const { iconSrc, view, iconAsset, iconName } =
    fullConfig.statuses[obj.status] || {};
  if (obj.status) {
    return createElement(
      "div",
      {
        class: "chart-matrix__popover",
      },
      createElement(
        "div",
        {
          class: "title",
        },
        createElement(
          "hbr-tag",
          { size: "small", accent: view.default.containerStyle.background },
          iconAsset
            ? createElement("hbr-icon", {
                slot: "prefix",
                asset: iconAsset,
                style: {
                  color: view.default.iconStyle.color,
                },
              })
            : iconName
            ? createElement("hbr-icon", {
                slot: "prefix",
                name: iconName,
                style: {
                  color: view.default.iconStyle.color,
                },
              })
            : iconSrc &&
              createElement("img", {
                slot: "prefix",
                src: iconSrc,
              }),
          obj.status
        )
      ),
      createElement("hbr-divider"),
      createElement(
        "table",
        {},
        createElement(
          "tr",
          {},
          createElement("td", {}, fullConfig?.axis?.rowLabel || "Row"),
          createElement("td", {}, row)
        ),
        createElement(
          "tr",
          {},
          createElement("td", {}, fullConfig?.axis?.colLabel || "Column"),
          createElement("td", {}, col)
        )
      )
    );
  }
  return createElement(
    "div",
    {
      class: "chart-matrix__popover",
    },
    createElement(
      "table",
      {},
      createElement(
        "tr",
        {},
        createElement("td", {}, fullConfig?.axis?.rowLabel || "Row"),
        createElement("td", {}, row)
      ),
      createElement(
        "tr",
        {},
        createElement("td", {}, fullConfig?.axis?.colLabel || "Column"),
        createElement("td", {}, col)
      )
    )
  );
};

const setDefaultAxisTooltipTemplate = (createElement, data) => {
  return createElement("div", {}, data);
};

const generateDataBlock = (
  complete2DAry,
  blockSize: number,
  gapSize: number,
  iconSize: number,
  marginLeft: number,
  marginTop: number,
  mode: "view" | "edit",
  fullConfig: MatrixChartConfig,
  selectedItems
) => {
  const {
    eventListeners: fullConfigEvents,
    statuses,
    accessibility,
  } = fullConfig;

  const eventListeners: {
    [k: string]: (event: Event) => void;
  } = [
    "onMouseEnter",
    "onMouseMove",
    "onMouseLeave",
    "onFocus",
    "onBlur",
    "onClick",
  ].reduce((acc, event) => {
    if (mode === "view") {
      acc[event] =
        fullConfigEvents?.[mode]?.[event] || fullConfigEvents?.[event]; // @deprecated event without mode
    } else {
      acc[event] = fullConfigEvents?.[mode]?.[event];
    }

    return acc;
  }, {});

  let counter = -1;

  return (
    <g class="matrix-grid" transform={`translate(${marginLeft},${marginTop})`}>
      {complete2DAry.reduce((acc, row, rowIndex) => {
        const cur = row.data.map((col, colIndex) => {
          const { iconAsset, iconName, iconSrc } = statuses[col.status] || {};
          counter += 1;

          return (
            <g
              key={`${row.row}-${col.col}`}
              width={blockSize}
              height={blockSize}
              x={colIndex * (blockSize + gapSize)}
              y={rowIndex * (blockSize + gapSize)}
            >
              <foreignObject
                class="grid-cell"
                data-row={row.row}
                data-col={col.col}
                data-status={col.status}
                data-index={counter}
                data-disabled={col.status === "disabled" ? "true" : "false"}
                data-selected={
                  mode === "edit" && selectedItems[`${row.row}-${col.col}`]
                    ? "true"
                    : "false"
                }
              >
                <div
                  tabIndex={0}
                  part="icon-container"
                  // biome-ignore lint/a11y/useSemanticElements: intentional use of div
                  role="button"
                  aria-label={
                    accessibility?.ariaLabel
                      ? accessibility?.ariaLabel(row, col)
                      : `${row.row} ${col.col}: ${col.status || ""}`
                  }
                  style={applyStylesFromState(
                    mode,
                    statuses,
                    selectedItems,
                    row,
                    col,
                    "containerStyle"
                  )}
                  onMouseEnter={eventListeners?.onMouseEnter}
                  onMouseMove={eventListeners?.onMouseMove}
                  onMouseLeave={eventListeners?.onMouseLeave}
                  onFocus={eventListeners?.onFocus}
                  onBlur={eventListeners?.onBlur}
                  onClick={eventListeners?.onClick}
                  onMouseOver={(event) => {
                    setCellStyleFromStateEvent(
                      event,
                      col,
                      statuses,
                      mode,
                      iconSize,
                      true
                    );
                  }}
                  onMouseOut={(event) => {
                    setCellStyleFromStateEvent(
                      event,
                      col,
                      statuses,
                      mode,
                      iconSize,
                      false
                    );
                  }}
                >
                  {iconAsset ? (
                    <hbr-icon
                      asset={statuses[col.status]?.iconAsset}
                      size={`${iconSize}px`}
                      style={applyStylesFromState(
                        mode,
                        statuses,
                        selectedItems,
                        row,
                        col,
                        "iconStyle"
                      )}
                      part="icon"
                    />
                  ) : iconName ? (
                    <hbr-icon
                      src={statuses[col.status]?.iconName}
                      style={applyStylesFromState(
                        mode,
                        statuses,
                        selectedItems,
                        row,
                        col,
                        "iconStyle"
                      )}
                      part="icon"
                    />
                  ) : (
                    iconSrc && (
                      <img
                        src={statuses[col.status]?.iconSrc}
                        style={applyStylesFromState(
                          mode,
                          statuses,
                          selectedItems,
                          row,
                          col,
                          "iconStyle"
                        )}
                        alt=""
                      />
                    )
                  )}
                </div>
              </foreignObject>
            </g>
          );
        });
        acc.push(...cur);
        return acc;
      }, [])}
    </g>
  );
};

const generateControlPanel = (
  onZooming,
  onSelection,
  mode,
  config: MatrixChartConfig,
  blockSize: number,
  controlRef,
  setRefCtrl
) => {
  const customSystemIcons = getBootstrapConfig()?.systemIcons;
  const { statuses, grid } = config;
  const { itemSizes } = grid;
  const infoBlock = Object.entries(statuses).map((pair) => {
    if (pair[1].iconAsset) {
      return (
        <div class="chart-matrix__info-block" key={pair[0]}>
          <hbr-icon
            asset={pair[1].iconAsset}
            style={pair[1].view.default.iconStyle}
          />
          <span>{pair[1].label}</span>
        </div>
      );
    }
    if (pair[1].iconName) {
      return (
        <div class="chart-matrix__info-block" key={pair[0]}>
          <hbr-icon
            name={pair[1].iconName}
            style={pair[1].view.default.iconStyle}
          />
          <span>{pair[1].label}</span>
        </div>
      );
    }
    if (pair[1].iconSrc) {
      return (
        <div class="chart-matrix__info-block" key={pair[0]}>
          <img
            src={pair[1].iconSrc}
            style={pair[1].view.default.iconStyle}
            alt=""
          />
          <span>{pair[1].label}</span>
        </div>
      );
    }
  });

  infoBlock.unshift(
    <div class="chart-matrix__info-block" key="default-block">
      <div
        style={{
          background: "var(--base-bg-default, #F7F7F7)",
          width: "14px",
          height: "14px",
          border: "1px dashed var(--control-border-default, #889099)",
          borderRadius: "4px",
        }}
      />
      <span>Default</span>
    </div>
  );
  return (
    <div
      class="chart-matrix__control"
      part="control"
      ref={setRefCtrl}
      onKeyDown={(event) => onCtrlPanelKeyDown(event, controlRef)}
    >
      <slot name="control-panel">
        <hbr-icon-button
          asset={customSystemIcons?.plus || plus}
          disabled={isZoomDisabled(true, itemSizes, blockSize)}
          onClick={() => onZooming(true)}
          style={{
            backgroundColor: isZoomDisabled(true, itemSizes, blockSize)
              ? "var(--control-bg-medium-disabled, #E1E4E8)"
              : "",
          }}
        />
        <hbr-divider noPadding />
        <hbr-icon-button
          asset={customSystemIcons?.minus || minus}
          disabled={isZoomDisabled(false, itemSizes, blockSize)}
          onClick={() => onZooming(false)}
          style={{
            backgroundColor: isZoomDisabled(false, itemSizes, blockSize)
              ? "var(--control-bg-medium-disabled, #E1E4E8)"
              : "",
          }}
        />
        <hbr-divider noPadding />
        <hbr-icon-button
          asset={customSystemIcons?.["check-square"] || checkSquare}
          onClick={onSelection}
          class={mode === "edit" ? "--selected" : ""}
        />
        <hbr-divider noPadding />
        <hbr-popover placement="left" hoist trigger="click hover">
          <hbr-icon-button asset={customSystemIcons?.info || info} />
          <div slot="content">{infoBlock}</div>
        </hbr-popover>
      </slot>
    </div>
  );
};

export {
  generateAxisTop,
  generateAxisLegendLeft,
  generateAxisRight,
  generateAxisBottom,
  generateControlPanel,
  generateDataBlock,
  setAxisHoveringState,
  setDefaultItemTooltipTemplate,
  setDefaultAxisTooltipTemplate,
};
